package com.pethop.adoption;
import com.pethop.adoption.dto.ApplicationDocumentResponse; import com.pethop.security.SecurityUser; import java.io.IOException; import java.util.List; import java.util.UUID; import org.springframework.core.io.InputStreamResource; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController public class ApplicationDocumentController{private final ApplicationDocumentService service;private final DocumentStorage files;public ApplicationDocumentController(ApplicationDocumentService s,DocumentStorage f){service=s;files=f;}
 @PostMapping(path="/api/v1/adoption-applications/{id}/documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) ApplicationDocumentResponse add(@AuthenticationPrincipal SecurityUser user,@PathVariable UUID id,@RequestParam String documentType,@RequestParam MultipartFile file)throws IOException{return service.add(user,id,documentType,file);}
 @GetMapping("/api/v1/adoption-applications/{id}/documents") List<ApplicationDocumentResponse> list(@AuthenticationPrincipal SecurityUser user,@PathVariable UUID id){return service.list(user,id);}
 @GetMapping("/api/v1/application-documents/{id}") ResponseEntity<InputStreamResource> get(@AuthenticationPrincipal SecurityUser user,@PathVariable UUID id)throws IOException{ApplicationDocument d=service.get(user,id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.getContentType())).contentLength(d.getFileSize()).cacheControl(CacheControl.noCache()).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.getOriginalFilename().replace("\"","_")+"\"").body(new InputStreamResource(files.open(d.getStoragePath())));}
}
